#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>

#define MAP_CAP 2048

typedef struct {
    int64_t *keys;
    int64_t *values;
    unsigned char *used;
} Map;

static uint64_t hash64(uint64_t x) {
    x ^= x >> 30;
    x *= UINT64_C(0xbf58476d1ce4e5b9);
    x ^= x >> 27;
    x *= UINT64_C(0x94d049bb133111eb);
    x ^= x >> 31;
    return x;
}

static void map_init(Map *m) {
    m->keys = (int64_t*)calloc(MAP_CAP, sizeof(int64_t));
    m->values = (int64_t*)calloc(MAP_CAP, sizeof(int64_t));
    m->used = (unsigned char*)calloc(MAP_CAP, sizeof(unsigned char));
}

static void map_free(Map *m) {
    free(m->keys);
    free(m->values);
    free(m->used);
}

static int64_t map_get(const Map *m, int64_t key) {
    size_t pos = (size_t)(hash64((uint64_t)key) & (MAP_CAP - 1));
    for (size_t step = 0; step < MAP_CAP; ++step) {
        if (!m->used[pos]) return 0;
        if (m->keys[pos] == key) return m->values[pos];
        pos = (pos + 1) & (MAP_CAP - 1);
    }
    return 0;
}

static void map_add(Map *m, int64_t key, int64_t delta) {
    size_t pos = (size_t)(hash64((uint64_t)key) & (MAP_CAP - 1));
    for (size_t step = 0; step < MAP_CAP; ++step) {
        if (!m->used[pos]) {
            m->used[pos] = 1;
            m->keys[pos] = key;
            m->values[pos] = delta;
            return;
        }
        if (m->keys[pos] == key) {
            m->values[pos] += delta;
            return;
        }
        pos = (pos + 1) & (MAP_CAP - 1);
    }
}

static int parse_array(const char *s, int *out) {
    int count = 0;
    const char *p = s;
    while (*p) {
        if (*p == '-' || (*p >= '0' && *p <= '9')) {
            char *end = NULL;
            long long value = strtoll(p, &end, 10);
            out[count++] = (int)value;
            p = end;
        } else {
            ++p;
        }
    }
    return count;
}

int numberOfArithmeticSlices(int *nums, int n) {
    Map *dp = (Map*)calloc((size_t)n, sizeof(Map));
    for (int i = 0; i < n; ++i) map_init(&dp[i]);

    int64_t answer = 0;

    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < i; ++j) {
            int64_t diff = (int64_t)nums[i] - (int64_t)nums[j];
            int64_t previous = map_get(&dp[j], diff);
            map_add(&dp[i], diff, previous + 1);
            answer += previous;
        }
    }

    for (int i = 0; i < n; ++i) map_free(&dp[i]);
    free(dp);
    return (int)answer;
}

