class Solution {
public:
    int numberOfArithmeticSlices(vector<int>& nums) {
        vector<unordered_map<long long, long long>> dp(nums.size());
        long long ans = 0;

        for (int i = 0; i < (int)nums.size(); ++i) {
            for (int j = 0; j < i; ++j) {
                long long d = (long long)nums[i] - nums[j];
                auto it = dp[j].find(d);
                long long prev = (it == dp[j].end()) ? 0 : it->second;
                dp[i][d] += prev + 1;
                ans += prev;
            }
        }
        return (int)ans;
    }
};

