class Solution {
    public int numberOfArithmeticSlices(int[] nums) {
        List<Map<Long, Long>> dp = new ArrayList<>(nums.length);
        for (int i = 0; i < nums.length; i++) {
            dp.add(new HashMap<>());
        }

        long ans = 0;
        for (int i = 0; i < nums.length; i++) {
            for (int j = 0; j < i; j++) {
                long d = (long) nums[i] - nums[j];
                long prev = dp.get(j).getOrDefault(d, 0L);
                dp.get(i).put(d, dp.get(i).getOrDefault(d, 0L) + prev + 1L);
                ans += prev;
            }
        }
        return (int) ans;
    }
}

