public class Main {
    private static int[] parseArray(String line) {
        String body = line.substring(1, line.length() - 1).trim();
        int left = body.indexOf('[');
        int right = body.lastIndexOf(']');
        String inner = body.substring(left + 1, right).trim();
        if (inner.isEmpty()) return new int[0];
        String[] parts = inner.split(",");
        int[] nums = new int[parts.length];
        for (int i = 0; i < parts.length; i++) {
            nums[i] = Integer.parseInt(parts[i].trim());
        }
        return nums;
    }

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String line = br.readLine().trim();
        int[] nums = parseArray(line);
        System.out.println(new Solution().numberOfArithmeticSlices(nums));
    }
}

